foreach($mCidades as $nCodigo_IBGE => $cCid) {
	list($cCidade,$cUF)=explode(",,",$cCid);

	$cSql_D020=mysql_query("SELECT * FROM D020 LEFT JOIN D018 ON D018_Id=D020_D018_Id WHERE D020_Nome_Cidade='".addslashes($cCidade)."' and D018_UF='{$cUF}'");
	$mD020=mysql_fetch_array($cSql_D020);
    echo mysql_error();
	    
	if (mysql_num_rows($cSql_D020)==0) {
		$cSql_D018=mysql_query("SELECT * FROM D018 WHERE D018_UF='{$cUF}'");
		$mD018=mysql_fetch_array($cSql_D018);

	    mysql_query("INSERT INTO D020 (D020_Codigo_IBGE,D020_Nome_Cidade,D020_D018_Id) VALUES ('{$nCodigo_IBGE}','".addslashes($cCidade)."','{$mD018['D018_Id']}')");
	    echo mysql_error();
	}

	if ($mD020['D020_Codigo_IBGE'] != $nCodigo_IBGE){
	    mysql_query("update D020 set D020_Codigo_IBGE='{$nCodigo_IBGE}' where D020_Id='{$mD020['D020_Id']}'");
	    echo mysql_error();
	}
}


$sqlC004 = mysql_query("SELECT * FROM C004 WHERE (IFNULL(C004_D018_Id,0) <= 0 AND IFNULL(C004_Uf,'') != '') OR (IFNULL(C004_D020_Id,0) <= 0 && IFNULL(C004_Cidade,'') != '')");
while($rowC004 = mysql_fetch_array($sqlC004)){
    if(is_numeric($rowC004['C004_Uf'])){
        $sqlD018 = mysql_query("SELECT D018_Id FROM D018 WHERE D018_Codigo_IBGE = '{$rowC004['C004_Uf']}'");
        $rowD018 = mysql_fetch_array($sqlD018);
        if($rowD018['D018_Id'] > 0){
            mysql_query("UPDATE C004 SET C004_D018_Id = '{$rowD018['D018_Id']}', C004_Uf = '' WHERE C004_Id = '{$rowC004['C004_Id']}'");
        }
    }
    if(is_numeric($rowC004['C004_Cidade'])){
        $sqlD020 = mysql_query("SELECT D020_Id FROM D020 WHERE D020_Codigo_IBGE = '{$rowC004['C004_Cidade']}'");
        $rowD020 = mysql_fetch_array($sqlD020);
        if($rowD020['D020_Id'] > 0){
            mysql_query("UPDATE C004 SET C004_D020_Id = '{$rowD020['D020_Id']}', C004_Cidade = '' WHERE C004_Id = '{$rowC004['C004_Id']}'");
        }
    }
}